INSERT INTO studio_styles (id, slug, label, description, prompt, tab, status, plans, engine, audience, sort_order, updated_at) VALUES
  (gen_random_uuid()::text, 'blossom_atrium', 'Blossom Atrium', 'Airy white atrium, cascading pink blossom vines, slat-light shadows', 'Place this outfit on a graceful Indian fashion model in a bright airy white-walled atrium with cascading pink jasmine blossom vines trailing from above and soft window-slat sun shadows across the wall and pale floor, relaxed editorial pose. The garment''s exact colour, pattern and embroidery stay 100% unchanged with neutral daylight on the fabric.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 0, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'boutique_showroom', 'Boutique Showroom', 'Indoor — upscale boutique, spot-lit displays, racks bokeh', 'Place this outfit on a graceful Indian fashion model inside an upscale fashion boutique with warm spot-lit displays and clothing racks softly out of focus behind. Even neutral lighting on the garment so its exact colour, pattern and embroidery stay unchanged.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 1, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'runway', 'Catwalk Runway', 'High-fashion catwalk runway setting with dramatic spotlights', 'Place this outfit in a high-fashion catwalk runway show with overhead spotlights and soft blurred audience bokeh in the background. A graceful Indian fashion model (Indian lady for womenswear / Indian gentleman for menswear / Indian boy for kids) is walking gracefully. The garment shape, drape, exact original color, embroidery, and texture are 100% preserved with true-tone lighting.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 2, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'copper_diamond', 'Copper Diamond Backdrop', 'White brick wall, rose-gold diamond frames, eucalyptus garlands', 'Place this outfit on a graceful Indian fashion model in front of a whitewashed brick wall styled with two nested rose-gold diamond frames, gold floral detailing, trailing eucalyptus-and-white-flower garlands, taper candles and geometric lanterns on a wood floor, soft event lighting. Garment colour and embroidery preserved exactly.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 3, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'dupatta_motion', 'Dupatta in Motion', 'Pose — mid-turn, dupatta and skirt caught in the air', 'Place this outfit on a graceful Indian fashion model captured mid-motion, turning with the dupatta and skirt caught in the air and a slight wind, soft neutral backdrop with gentle motion blur only in the background. The garment stays sharp with colour, drape and embroidery 100% preserved.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['womens']::text[], 4, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'rooftop_golden', 'Golden-Hour Rooftop', 'City rooftop, string lights, blurred skyline, sun flare', 'Place this outfit on a graceful Indian fashion model on a chic city rooftop at golden hour with string lights and a blurred skyline, warm sun flare behind, relaxed editorial pose. Neutral light on the fabric keeps the garment colour and detail true.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 5, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'gradient_hero', 'Gradient Campaign Hero', 'Colour-gradient backdrop, beauty light, room for text', 'Place this outfit on a graceful Indian fashion model against a smooth studio colour-gradient backdrop (deep plum to warm rose) with even beauty lighting, centred campaign-hero framing with head-to-hem clearance for text. The garment colour, pattern and embroidery are exactly preserved.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 6, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'heritage_library', 'Grand Heritage Library', 'Indoor — wood panelling, tall bookshelves, brass lamps', 'Place this garment on a graceful Indian fashion model inside a grand wood-panelled heritage library with tall bookshelves and brass reading lamps, warm soft interior light behind and neutral light on the subject, poised standing pose. Colour, texture and embroidery preserved exactly.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 7, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'heritage_street', 'Jaipur Heritage Street', 'Outdoor — terracotta-pink walls, carved doors, candid stride', 'Place this garment on a graceful Indian fashion model on a Jaipur old-city street with terracotta-pink carved walls, antique wooden doors and brass lanterns, soft morning light, candid mid-stride pose. Exact dyes, weave and embroidery stay faithful to the original.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 8, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'lakeside_deck', 'Lakeside Deck View', 'Wooden deck, carved balustrade, emerald lake, forested hills', 'Place this garment on a graceful Indian fashion model on a wooden lakeside deck with a carved reddish-brown balustrade, a calm emerald-green lake, forested mountains and a soft overcast sky behind. Diffused daylight keeps the garment colour, drape and embroidery true.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 9, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'mall_concourse', 'Modern Mall Concourse', 'Cream tile floor, glass storefronts, fan-palms, water feature', 'Place this outfit on a graceful Indian fashion model in a spacious modern shopping-mall concourse with a glossy cream tile floor, tall glass storefronts softly out of focus, potted fan-palms and a low water feature, bright even ceiling light, candid pose. Exact garment colour, pattern and embroidery unchanged.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 10, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'pastel_gradient', 'Pastel Gradient Lounge', 'Teal-to-blush gradient wall, pink pampas grass, blush rug', 'Place this outfit on a graceful Indian fashion model in a minimalist studio lounge with a smooth teal-to-blush gradient wall, tall pink pampas grass in ceramic vases either side, a pale wood floor and a round blush rug, even soft lighting. The garment''s exact colour, pattern and embroidery stay 100% unchanged.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 11, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'botanical_garden', 'Royal Botanical Garden', 'Outdoor — Mughal garden, marble fountain, golden-hour bokeh', 'Place this outfit on a graceful Indian fashion model in a lush Mughal-style botanical garden with manicured hedges, a marble fountain and blooming flowerbeds, soft golden-hour daylight and greenery bokeh behind. Neutral daylight on the garment keeps its true colour, texture and embroidery.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 12, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'seated_haveli_steps', 'Seated Haveli Steps', 'Pose — seated on carved stone steps, dupatta on lap', 'Place this outfit on a graceful Indian fashion model seated on carved stone haveli steps with the dupatta arranged across the lap, potted palms and a lantern softly out of focus behind, full garment visible. Neutral daylight keeps true colour and zari.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['womens']::text[], 13, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'studiomodel', 'Studio Editorial', 'High-fashion Indian studio model wearing the outfit with softbox lighting', 'Place this garment naturally onto a professional Indian fashion model in a clean editorial studio. The model has an elegant posture and natural expression. The garment shape, exact original color, dye, pattern, and embroidery are 100% preserved with realistic draping. Color-true 5500K neutral studio softbox lighting with soft grounding shadows. No color shifts.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 14, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'teen_street', 'Teen Street Style', 'Teen model against a painted-mural brick wall, streetwear stance', 'Place this outfit on the model against a colourful painted-mural brick wall on an urban street, a relaxed streetwear stance with hands in pockets, bright overcast daylight, blurred bicycles and string lights behind. The garment shape, exact original colour, pattern and embroidery are 100% preserved with true-tone lighting.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['teen_girl','teen_boy']::text[], 15, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'tree_tunnel', 'Tree-Tunnel Avenue', 'Arching green canopy, cobblestone path, moss strip, tulip beds', 'Place this outfit on a graceful Indian fashion model standing at the centre of a symmetrical tree-tunnel avenue, an arching green canopy overhead, a cobblestone path with a bright green moss strip down the middle and tulip flowerbeds on both sides, soft overcast light. The garment colour, texture and embroidery stay true.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 16, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'editorial_vogue', 'Vogue Editorial', 'Magazine editorial — grey cyclorama, softbox key + hair light', 'Place this outfit on a graceful Indian fashion model in a high-fashion editorial studio with a seamless mid-grey backdrop, softbox key light and a subtle hair light, confident straight-on pose. The garment shape, drape, exact original colour, pattern and embroidery are 100% preserved.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 17, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'male_with_car', 'Male with Car', 'Model beside a premium car on an open road, golden hour', 'Place this outfit on the model standing beside a glossy premium sedan on an open coastal road at golden hour, one hand resting on the roof, warm low sun with a soft lens flare, blurred asphalt and hills behind. The garment shape, exact original colour, pattern and embroidery are 100% preserved with true-tone lighting.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['mens','teen_boy']::text[], 18, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'male_with_bike', 'Male with Bike', 'Model beside a classic motorcycle on a city street', 'Place this outfit on the model beside a classic chrome-and-black motorcycle on a quiet city street, one foot on the kerb, warm afternoon light, blurred shopfronts and parked cars behind. The garment shape, exact original colour, pattern and embroidery are 100% preserved with true-tone lighting.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['mens','teen_boy']::text[], 19, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'kids_playing', 'Kids Playing Outdoors', 'Child mid-play in a sunny park, candid, greenery bokeh', 'Place this outfit on the child mid-play in a sunny park, running across bright green grass with arms out and a joyful expression, soft bokeh of trees and a swing set behind, warm afternoon daylight. The garment shape, exact original colour, pattern and embroidery are 100% preserved with true-tone lighting.', 'MODEL'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY['kids_boy','kids_girl']::text[], 20, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'display_hanger', 'Styled Hanger', 'No model — garment re-hung on a polished walnut hanger, white studio', 'Product-only studio shot, no person, model or mannequin anywhere in the frame. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then hang the garment on a polished walnut wooden hanger against a seamless white studio backdrop, even 5500K lighting, with a soft natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 21, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'studio_home', 'Lifestyle Home Studio', 'No model — garment on a wooden hanger, pale wood wall + soft plant', 'Product-only lifestyle shot, no person, model or mannequin anywhere in the frame. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then hang the garment on a wooden hanger against a pale wooden wall panel with a trailing plant softly out of focus beside it, warm window daylight, with a soft natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 22, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'studio_minimal', 'Minimal Clean Studio', 'No model — garment on a slim matte-white hanger, empty off-white space', 'Product-only studio shot, no person, model or mannequin anywhere in the frame. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then hang the garment on a slim matte-white hanger against a minimal off-white background with generous empty space around it, flat even lighting, with a faint natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 23, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'display_mannequin', 'Mannequin Presentation', 'No model — garment fitted on a clean white headless mannequin', 'Product presentation shot, no living person or fashion model. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then fit the garment naturally onto a clean white headless mannequin form against a seamless white studio backdrop, even 5500K lighting, with a soft natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 24, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'studio_pro', 'Professional Studio', 'No model — garment on a wooden hanger, seamless mid-grey studio', 'Product-only studio shot, no person, model or mannequin anywhere in the frame. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then hang the garment on a premium wooden hanger against a seamless mid-grey professional photography studio backdrop, even 5500K softbox lighting, with a soft natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 25, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'studio_beige', 'Warm Beige Studio', 'No model — garment on a wooden hanger, warm beige backdrop', 'Product-only studio shot, no person, model or mannequin anywhere in the frame. Keep the garment 100% pixel-identical — do not alter its shoulders, neckline, sleeves, colour, print or embroidery. Remove the original hanger, hook, clips and pegs, then hang the garment on a wooden hanger against a warm beige studio backdrop with subtle depth, soft warm-neutral 5500K lighting, with a soft natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 26, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'wedding_elegant', 'Wedding Florals', 'Elegant wedding backdrop with floral arrangements and draping', 'Replace the background of this product photo with an elegant wedding backdrop featuring soft floral arrangements and pastel draping in the background. The garment itself is lit with neutral daylight studio lighting, keeping its original fabric color, embroidery, and textures 100% faithful to the original photo.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 27, CURRENT_TIMESTAMP),
  (gen_random_uuid()::text, 'warm_luxury', 'Warm Luxury', 'Rich warm beige backdrop with color-true subject lighting', 'Replace the background of this product photo with a warm, luxurious beige studio backdrop with subtle depth. The product itself is lit with neutral, color-true 5500K studio light so the garment fabric color, dye, and embroidery remain 100% faithful to the original photo with natural grounding shadow.', 'PRODUCT'::"StudioStyleTab", 'DRAFT'::"StudioStyleStatus", '{}'::"SubscriptionPlan"[], NULL, ARRAY[]::text[], 28, CURRENT_TIMESTAMP);
